/**
 * components/GeneratedFiles.jsx
 * Owner: Roshan
 * Shows files generated by the agent (DOCX, XLSX, PPTX) with download buttons.
 */

import { useEffect, useState } from 'react';
import { getFiles } from '../services/api';

const FILE_ICONS = {
  docx: '📝',
  xlsx: '📊',
  pptx: '📑',
  pdf:  '📄',
  txt:  '📃',
};

const FILE_COLORS = {
  docx: 'var(--accent-blue)',
  xlsx: 'var(--accent-green)',
  pptx: 'var(--accent-amber)',
};

export default function GeneratedFiles({ newFiles }) {
  const [files, setFiles]     = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getFiles()
      .then(setFiles)
      .catch(() => setFiles([]))
      .finally(() => setLoading(false));
  }, []);

  // Merge in any new files from chat response
  useEffect(() => {
    if (newFiles && newFiles.length > 0) {
      setFiles((prev) => {
        const names = new Set(prev.map((f) => f.name));
        const merged = [...prev, ...newFiles.filter((f) => !names.has(f.name))];
        return merged;
      });
    }
  }, [newFiles]);

  if (loading) {
    return (
      <div>
        <p className="section-label">Generated Files</p>
        <div style={{ display: 'flex', gap: 6, alignItems: 'center', color: 'var(--text-muted)', fontSize: '0.8rem' }}>
          <div className="spinner" /> Loading…
        </div>
      </div>
    );
  }

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
        <p className="section-label" style={{ margin: 0 }}>Generated Files</p>
        {files.length > 0 && (
          <span style={{ fontSize: '0.7rem', color: 'var(--text-muted)' }}>{files.length} file{files.length !== 1 ? 's' : ''}</span>
        )}
      </div>

      {files.length === 0 ? (
        <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
          No files generated yet.
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
          {files.map((file, i) => {
            const ext = file.type || file.name?.split('.').pop() || '';
            const color = FILE_COLORS[ext] || 'var(--accent-cyan)';
            return (
              <div
                key={i}
                className="fade-in"
                style={{
                  display: 'flex', alignItems: 'center', gap: 8,
                  padding: '0.55rem 0.75rem',
                  background: 'var(--bg-secondary)',
                  borderRadius: 'var(--radius-md)',
                  border: '1px solid var(--border)',
                  animationDelay: `${i * 0.05}s`,
                  animationFillMode: 'both',
                }}
              >
                <span style={{ fontSize: '1.1rem' }}>{FILE_ICONS[ext] || '📁'}</span>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{
                    fontSize: '0.78rem', fontWeight: 500,
                    overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                    color: color,
                  }}>
                    {file.name}
                  </div>
                  {file.size && (
                    <div style={{ fontSize: '0.65rem', color: 'var(--text-muted)' }}>{file.size}</div>
                  )}
                </div>
                <div style={{ display: 'flex', gap: 4 }}>
                  <button
                    id={`open-file-${i}`}
                    className="btn btn-secondary btn-icon"
                    title="Open"
                    style={{ fontSize: '0.7rem', padding: '3px 8px' }}
                  >
                    Open
                  </button>
                  <button
                    id={`download-file-${i}`}
                    className="btn btn-primary btn-icon"
                    title="Download"
                    style={{ fontSize: '0.7rem', padding: '3px 8px' }}
                  >
                    ↓
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
